      text-transform: none;
      font-style: normal;
      line-height: 1.7;
      font-family: 'IBM Plex Sans Arabic', sans-serif;
    }

    body {
      font-family: 'IBM Sans', 'IBM Plex Sans Arabic', sans-serif;
